fn diag_val(i: isize, j: isize) -> f64 {
    if i == j {
        1.0
    } else {
        0.0
    }
}

fn identity(n: usize) -> Vec<Vec<f64>> {
    (0..n)
        .map(|i| {
            (0..n)
                .map(|j| diag_val(i as isize, j as isize))
                .collect()
        })
        .collect()
}

fn main() {
    // Examples
    let id0 = identity(0);
    assert_eq!(id0, vec![]);

    let id1 = identity(1);
    assert_eq!(id1, vec![vec![1.0]]);

    let id3 = identity(3);
    assert_eq!(
        id3,
        vec![
            vec![1.0, 0.0, 0.0],
            vec![0.0, 1.0, 0.0],
            vec![0.0, 0.0, 1.0],
        ]
    );
}